css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; border-radius: 8px; }
.loader .buoy { position: absolute; left: 36%; top: 18%; width: 28%; height: 48%; border-radius: 40% 40% 26% 26% / 24% 24% 18% 18%; background: repeating-linear-gradient(var(--accent) 0 22%, color-mix(in srgb, #fff 70%, var(--accent)) 0 44%); transform-origin: 50% 100%; animation: buoy-rock calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
.loader .lamp { position: absolute; left: 26%; bottom: 96%; width: 48%; height: 22%; border-radius: 50%; background: var(--accent-2); animation: buoy-flash calc(var(--loader-speed) * 1.1) ease-in-out infinite; }
.loader .swell { position: absolute; left: -26%; width: 152%; height: 26%; border-radius: 50% 50% 0 0 / 100% 100% 0 0; animation: buoy-swell calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .swell:nth-of-type(2) { bottom: 14%; background: color-mix(in srgb, var(--accent-2) 55%, transparent); }
.loader .swell:nth-of-type(3) { bottom: 0; height: 32%; background: color-mix(in srgb, var(--accent-2) 85%, transparent); animation-delay: calc(var(--loader-speed) * -1.5); }
@keyframes buoy-rock { 0%, 100% { transform: translateY(0) rotate(-9deg); } 50% { transform: translateY(-8%) rotate(9deg); } }
@keyframes buoy-flash { 0%, 55% { opacity: .3; box-shadow: none; } 68%, 82% { opacity: 1; box-shadow: 0 0 14px var(--accent-2); } 100% { opacity: .3; box-shadow: none; } }
@keyframes buoy-swell { 0%, 100% { transform: translateX(-6%); } 50% { transform: translateX(6%); } }
